using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;

namespace MyApp.Evals;

[TestClass]
public sealed class EvalTests
{
    private static ReportingConfiguration? s_reportingConfiguration;

    [AssemblyInitialize]
    public static void Initialize(TestContext context)
    {
        s_reportingConfiguration = new ReportingConfiguration(
            storage: new DiskBasedReportingStorage(Path.Combine(context.TestRunResultsDirectory!, "eval-results")),
            evaluators:
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new FluencyEvaluator(),
            ],
            chatConfiguration: GetChatConfiguration(),
            interpretationProvider: new ScenarioRunInterpretationProvider());
    }

    private static ChatConfiguration GetChatConfiguration()
    {
        return new ChatConfiguration(chatClient: null!);
    }

    [TestMethod]
    public async Task GreetingIsCoherentAndRelevant()
    {
        await using var scenario = await s_reportingConfiguration!.CreateScenarioRunAsync(
            scenarioName: nameof(GreetingIsCoherentAndRelevant));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Say hello and introduce yourself briefly."),
            new(ChatRole.Assistant, "Hello! I'm an AI assistant here to help you."),
        };

        await scenario.EvaluateAsync(messages);

        scenario.AssertNumericMetricMeetsThreshold(CoherenceEvaluator.CoherenceMetricName, 3);
        scenario.AssertNumericMetricMeetsThreshold(RelevanceEvaluator.RelevanceMetricName, 3);
        scenario.AssertNumericMetricMeetsThreshold(FluencyEvaluator.FluencyMetricName, 3);
    }

    [TestMethod]
    public async Task AnswerIsRelevantToQuestion()
    {
        await using var scenario = await s_reportingConfiguration!.CreateScenarioRunAsync(
            scenarioName: nameof(AnswerIsRelevantToQuestion));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?"),
            new(ChatRole.Assistant, "The capital of France is Paris."),
        };

        await scenario.EvaluateAsync(messages);

        scenario.AssertNumericMetricMeetsThreshold(CoherenceEvaluator.CoherenceMetricName, 4);
        scenario.AssertNumericMetricMeetsThreshold(RelevanceEvaluator.RelevanceMetricName, 4);
        scenario.AssertNumericMetricMeetsThreshold(FluencyEvaluator.FluencyMetricName, 4);
    }
}

